//! Disk-backed synthetic rehearsal, NOT a migration CLI or completion protocol.
//! Fixtures are generated by actual deployed3ca plus the recorded tiny example.
//! All source frames are required in this test scope. There is no admission,
//! application descriptor interpretation, cache-math validation or GC proof.
//!
//! Explicit manual gate: in the isolated deployed3ca producer tree, run
//! `cargo run --release --offline --locked -p triblespace-core --no-default-features
//! --example legacy32_native_fixture -- /absolute/fresh/fixtures` using the
//! separately preserved producer patch. Then in this candidate run
//! `LEGACY32_NATIVE_FIXTURES=/absolute/fresh/fixtures cargo test --release
//! --offline --locked -p trible --no-default-features
//! canonical::rehearsal_tests -- --ignored --nocapture`.
//! No mirrored fallback or silent success when fixtures are missing. Optional
//! NATIVE_REHEARSAL_ATTEMPTS names an existing owned directory to retain the
//! otherwise temporary synthetic output attempts. Build locks/resource checks
//! remain required outside this test harness.
use super::frame as old_frame;
use super::legacy32;

use std::fs::{File, OpenOptions};
use std::io::Write;
use std::os::unix::fs::{OpenOptionsExt, PermissionsExt};
use std::path::{Path, PathBuf};

use ed25519_dalek::SigningKey;
use legacy32::{Input, Outcome};
use triblespace_core::capability::CapabilityProof;
use triblespace_core::collection::records::{
    CollectionCommit, CollectionDerive, CollectionMap, CollectionMerge, CollectionRecord,
    SourceLocator, KIND_COLLECTION_COMMIT, KIND_COLLECTION_DERIVE, KIND_COLLECTION_MAP,
    KIND_COLLECTION_MERGE,
};
use triblespace_core::collection::{CollectionRead, CollectionStore};
use triblespace_core::inline::Inline;
use triblespace_core::patch::{Entry, PATCH};
use triblespace_core::repo::pile::{OpaqueKind, PileFile, PileRecordContent, PileRecords};
use triblespace_core::repo::SnapshotSource;

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
enum Stop {
    Never,
    AfterBlobs,
    AfterOneAssertion,
    BeforeMarker,
}

#[derive(Debug, Default, PartialEq, Eq)]
struct Ids {
    assertions: PATCH<32>,
    proofs: PATCH<32>,
    blobs: PATCH<32>,
}

// Per-attempt workflow result, not a stored authority schema or shadow catalogue.
// Original evidence remains the immutable source file bound by source_hash.
#[derive(Debug)]
struct Attempt {
    source_hash: [u8; 32],
    completed: bool,
    interrupted: bool,
    issues: Vec<(usize, String)>,
    relations: Vec<([u8; 32], [u8; 32])>,
    ids: Option<Ids>,
}

fn insert(set: &mut PATCH<32>, id: [u8; 32]) {
    set.insert(&Entry::new(&id));
}
fn key(n: u8) -> SigningKey {
    SigningKey::from_bytes(&[n; 32])
}
fn payload(n: usize) -> [u8; 32] {
    *blake3::hash(format!("native-rewrite-synthetic-payload-{n}").as_bytes()).as_bytes()
}
fn fixture(name: &str) -> PathBuf {
    PathBuf::from(
        std::env::var_os("LEGACY32_NATIVE_FIXTURES")
            .expect("set LEGACY32_NATIVE_FIXTURES to the actual3ca producer output"),
    )
    .join(name)
}
fn file_hash(path: &Path) -> [u8; 32] {
    *blake3::hash(&std::fs::read(path).unwrap()).as_bytes()
}
fn fresh(path: &Path) -> File {
    OpenOptions::new()
        .write(true)
        .create_new(true)
        .mode(0o600)
        .open(path)
        .unwrap()
}

fn workspace(label: &str) -> tempfile::TempDir {
    match std::env::var_os("NATIVE_REHEARSAL_ATTEMPTS") {
        Some(base) => tempfile::Builder::new()
            .prefix(label)
            .tempdir_in(base)
            .unwrap(),
        None => tempfile::tempdir().unwrap(),
    }
}

fn retain(temp: tempfile::TempDir) {
    if std::env::var_os("NATIVE_REHEARSAL_ATTEMPTS").is_some() {
        println!("retained synthetic attempts: {}", temp.keep().display());
    }
}

// Synthetic remote-author side only. Neither B nor C key enters attempt().
// Current constructors are independent of the old transcript/frame adapter.
fn remote_refreshes() -> Vec<CollectionRecord> {
    let mut records = Vec::new();
    for n in [8, 9] {
        records.push(CollectionRecord::Commit(CollectionCommit::sign(
            &key(n),
            Inline::new(payload(0)),
            Inline::new(payload(1)),
            Inline::new(payload(2)),
        )));
        records.push(CollectionRecord::Derive(CollectionDerive::sign(
            &key(n),
            Inline::new(payload(3)),
            SourceLocator::of(payload(1)),
            Inline::new(payload(4)),
        )));
    }
    records
}

/// Reopen the output both as physical frames and through the native index.
/// Every hash/signature is checked, not inferred from a successful append.
fn verify_output(path: &Path) -> (Ids, PATCH<32>) {
    let frames = PileRecords::open(path).unwrap();
    let bytes = frames.bytes().clone();
    let mut ids = Ids::default();
    let mut raw_frames = PATCH::new();
    for frame in frames {
        let frame = frame.unwrap();
        insert(
            &mut raw_frames,
            *blake3::hash(&bytes[frame.offset..frame.offset + frame.len]).as_bytes(),
        );
        match frame.content {
            PileRecordContent::Blob {
                hash,
                data_offset,
                data_len,
                ..
            } => {
                assert_eq!(
                    blake3::hash(&bytes[data_offset..data_offset + data_len]).as_bytes(),
                    &hash.raw
                );
                insert(&mut ids.blobs, hash.raw);
            }
            PileRecordContent::CapabilityProof {
                id,
                data_offset,
                data_len,
            } => {
                let proof =
                    CapabilityProof::from_bytes(&bytes[data_offset..data_offset + data_len])
                        .unwrap();
                proof.verify_signatures().unwrap();
                assert_eq!(proof.id(), id);
                insert(&mut ids.proofs, id.raw);
            }
            PileRecordContent::Collection { record } => {
                record.verify_strict().unwrap();
                assert_eq!(
                    record.fingerprint().raw(),
                    *blake3::hash(&record.to_bytes()).as_bytes()
                );
                insert(&mut ids.assertions, record.fingerprint().raw());
            }
            other => panic!("unexpected output frame {other:?}"),
        }
    }
    let mut pile = PileFile::open_read_only(path).unwrap();
    let snapshot = pile.snapshot().unwrap();
    let mut indexed = PATCH::new();
    for record in snapshot.records().unwrap() {
        let record = record.unwrap();
        record.verify_strict().unwrap();
        insert(&mut indexed, record.fingerprint().raw());
    }
    assert_eq!(indexed, ids.assertions);
    pile.close().unwrap();
    (ids, raw_frames)
}

fn attempt(
    source: &Path,
    expected_source: [u8; 32],
    dir: &Path,
    local: &SigningKey,
    refreshes: &[CollectionRecord],
    stop: Stop,
) -> Attempt {
    assert_eq!(
        file_hash(source),
        expected_source,
        "source evidence changed before attempt"
    );
    std::fs::create_dir(dir).unwrap(); // Every retry must be a new attempt.
    let destination = dir.join("output.pile");
    let mut writer = fresh(&destination);
    let mut result = Attempt {
        source_hash: expected_source,
        completed: false,
        interrupted: false,
        issues: Vec::new(),
        relations: Vec::new(),
        ids: None,
    };
    let mut expected = Ids::default();
    let mut copied_frames = PATCH::new();
    let frames = PileRecords::open(source).unwrap();
    let bytes = frames.bytes().clone();
    // First streaming pass validates and copies the unchanged substrate.
    for frame in frames {
        let frame = match frame {
            Ok(frame) => frame,
            Err(error) => {
                result
                    .issues
                    .push((bytes.len(), format!("framing: {error:?}")));
                break;
            }
        };
        let copy = match frame.content {
            PileRecordContent::Blob {
                hash,
                data_offset,
                data_len,
                ..
            } => {
                if *blake3::hash(&bytes[data_offset..data_offset + data_len]).as_bytes() == hash.raw
                {
                    insert(&mut expected.blobs, hash.raw);
                    true
                } else {
                    result.issues.push((frame.offset, "blob hash".into()));
                    false
                }
            }
            PileRecordContent::CapabilityProof {
                data_offset,
                data_len,
                ..
            } => {
                match legacy32::convert(
                    Input::Auth(&bytes[data_offset..data_offset + data_len]),
                    None,
                )
                .outcome
                {
                    Outcome::UnchangedAuth { id } => {
                        insert(&mut expected.proofs, id);
                        true
                    }
                    Outcome::Invalid(error) => {
                        result
                            .issues
                            .push((frame.offset, format!("AUTH invalid: {error:?}")));
                        false
                    }
                    other => {
                        result
                            .issues
                            .push((frame.offset, format!("AUTH: {other:?}")));
                        false
                    }
                }
            }
            PileRecordContent::Opaque {
                kind: OpaqueKind::Described(_),
            } => false, // Pass two.
            other => {
                result.issues.push((
                    frame.offset,
                    format!("unsupported required frame: {other:?}"),
                ));
                false
            }
        };
        if copy {
            let raw = &bytes[frame.offset..frame.offset + frame.len];
            writer.write_all(raw).unwrap();
            insert(&mut copied_frames, *blake3::hash(raw).as_bytes());
        }
    }
    writer.sync_all().unwrap();
    drop(writer); // Never overlap a raw writer with PileFile append ownership.
    if stop == Stop::AfterBlobs {
        result.interrupted = true;
        return result;
    }

    let mut pile = PileFile::open(&destination).unwrap();
    pile.publish_record_kind_descriptions().unwrap();
    // Second streaming pass: originals remain in source; only strictly verified
    // and explicitly accounted-for current assertions enter destination.
    for frame in PileRecords::open(source).unwrap() {
        let Ok(frame) = frame else {
            break;
        }; // First pass already recorded failure.
        let PileRecordContent::Opaque {
            kind: OpaqueKind::Described(kind),
        } = frame.content
        else {
            continue;
        };
        let tagged = match old_frame::tagged(kind, &bytes[frame.offset..frame.offset + frame.len]) {
            Ok(tagged) => tagged,
            Err(error) => {
                result
                    .issues
                    .push((frame.offset, format!("old frame: {error:?}")));
                continue;
            }
        };
        // Try explicit refreshes by exact semantic equality, never by payload
        // membership alone. A list scan here is tiny ephemeral test input, not
        // a retained catalogue or alternative authority index.
        let refresh = refreshes.iter().find(|refresh| {
            matches!(
                legacy32::reseal_or_refresh(Input::TaggedCollection(&tagged), local, Some(refresh))
                    .outcome,
                Outcome::Converted { .. }
            ) && matches!(tagged[0], 1 | 9)
        });
        let converted =
            legacy32::reseal_or_refresh(Input::TaggedCollection(&tagged), local, refresh);
        assert_eq!(converted.original, tagged);
        match converted.outcome {
            Outcome::Converted {
                record,
                new_fingerprint,
            } => {
                let old = converted.old_fingerprint.unwrap();
                assert_ne!(old, new_fingerprint);
                result.relations.push((old, new_fingerprint));
                insert(&mut expected.assertions, new_fingerprint);
                pile.insert(record).unwrap();
                if stop == Stop::AfterOneAssertion {
                    pile.flush().unwrap();
                    pile.close().unwrap();
                    result.interrupted = true;
                    return result;
                }
            }
            other => result
                .issues
                .push((frame.offset, format!("assertion: {other:?}"))),
        }
    }
    pile.close().unwrap();
    let (actual, actual_frames) = verify_output(&destination);
    assert_eq!(actual.assertions, expected.assertions);
    assert_eq!(actual.proofs, expected.proofs);
    for id in expected.blobs.iter() {
        assert!(actual.blobs.get(&id).is_some());
    }
    for id in copied_frames.iter() {
        assert!(actual_frames.get(&id).is_some(), "copied frame changed");
    }
    for kind in [
        KIND_COLLECTION_COMMIT,
        KIND_COLLECTION_DERIVE,
        KIND_COLLECTION_MAP,
        KIND_COLLECTION_MERGE,
    ] {
        assert!(
            actual.blobs.get(&kind).is_some(),
            "current kind description absent"
        );
    }
    assert_eq!(
        file_hash(source),
        expected_source,
        "source evidence changed during attempt"
    );
    result.ids = Some(actual);
    if stop == Stop::BeforeMarker {
        result.interrupted = true;
        return result;
    }
    if !result.issues.is_empty() {
        return result;
    }
    // Test-local controlled completion marker only, not a format or public API.
    // The output was closed/reopened/verified first. Flush directory boundaries
    // too; this does NOT establish arbitrary power-loss or concurrent safety.
    File::open(dir).unwrap().sync_all().unwrap();
    let mut marker = fresh(&dir.join("complete.test-only"));
    writeln!(
        marker,
        "synthetic source={} assertions={} proofs={} blobs={}",
        hex::encode(expected_source),
        expected.assertions.len(),
        expected.proofs.len(),
        result.ids.as_ref().unwrap().blobs.len()
    )
    .unwrap();
    marker.sync_all().unwrap();
    drop(marker);
    File::open(dir).unwrap().sync_all().unwrap();
    result.completed = true;
    result
}

#[test]
#[ignore = "manual actual deployed /32 writer fixtures; see module instructions"]
fn deployed_native_frames_reseal_and_refresh_without_losing_distinct_assertions() {
    let source = fixture("complete.pile");
    let before = file_hash(&source);
    let temp = workspace("complete-");
    let dir = temp.path().join("attempt");
    let result = attempt(
        &source,
        before,
        &dir,
        &key(7),
        &remote_refreshes(),
        Stop::Never,
    );
    assert!(result.completed, "{:?}", result.issues);
    assert_eq!(result.source_hash, before);
    assert_eq!(result.relations.len(), 9);
    for (old, new) in &result.relations {
        println!("relation old={} new={}", hex::encode(old), hex::encode(new));
    }
    let ids = result.ids.unwrap();
    assert_eq!(ids.assertions.len(), 9);
    let mut expected = PATCH::new();
    for record in remote_refreshes() {
        insert(&mut expected, record.fingerprint().raw());
    }
    for metadata in [2, 5] {
        insert(
            &mut expected,
            CollectionCommit::sign(
                &key(7),
                Inline::new(payload(0)),
                Inline::new(payload(1)),
                Inline::new(payload(metadata)),
            )
            .fingerprint()
            .raw(),
        );
    }
    insert(
        &mut expected,
        CollectionDerive::sign(
            &key(7),
            Inline::new(payload(3)),
            SourceLocator::of(payload(1)),
            Inline::new(payload(4)),
        )
        .fingerprint()
        .raw(),
    );
    insert(
        &mut expected,
        CollectionMap::sign(
            &key(7),
            Inline::new(payload(6)),
            Inline::new(payload(1)),
            Inline::new(payload(7)),
        )
        .fingerprint()
        .raw(),
    );
    insert(
        &mut expected,
        CollectionMerge::sign(
            &key(7),
            Inline::new(payload(0)),
            (8..16).map(|n| Inline::new(payload(n))),
            Inline::new(payload(16)),
        )
        .unwrap()
        .fingerprint()
        .raw(),
    );
    assert_eq!(
        ids.assertions, expected,
        "every semantic field must survive actual old writer conversion"
    );
    assert_eq!(ids.proofs.len(), 1);
    assert_eq!(
        std::fs::metadata(dir.join("output.pile"))
            .unwrap()
            .permissions()
            .mode()
            & 0o777,
        0o600
    );
    assert_eq!(file_hash(&source), before);
    println!(
        "complete source={} assertions=9 proofs=1 blobs={}",
        hex::encode(before),
        ids.blobs.len()
    );
    retain(temp);
}

#[test]
#[ignore = "manual actual deployed /32 writer fixtures; see module instructions"]
fn controlled_interruptions_require_fresh_attempt_and_repeat_semantic_sets() {
    let source = fixture("complete.pile");
    let before = file_hash(&source);
    let temp = workspace("interruptions-");
    let refreshes = remote_refreshes();
    let baseline = attempt(
        &source,
        before,
        &temp.path().join("baseline"),
        &key(7),
        &refreshes,
        Stop::Never,
    );
    for (i, stop) in [
        Stop::AfterBlobs,
        Stop::AfterOneAssertion,
        Stop::BeforeMarker,
    ]
    .into_iter()
    .enumerate()
    {
        let dir = temp.path().join(format!("interrupted-{i}"));
        let partial = attempt(&source, before, &dir, &key(7), &refreshes, stop);
        assert!(partial.interrupted && !partial.completed);
        assert!(!dir.join("complete.test-only").exists());
        let (partial_ids, _) = verify_output(&dir.join("output.pile"));
        assert_eq!(partial_ids.assertions.len(), [0, 1, 9][i]);
        assert_eq!(partial_ids.proofs.len(), 1);
        let partial_hash = file_hash(&dir.join("output.pile"));
        let retry = attempt(
            &source,
            before,
            &temp.path().join(format!("retry-{i}")),
            &key(7),
            &refreshes,
            Stop::Never,
        );
        assert!(retry.completed);
        assert_eq!(retry.ids, baseline.ids);
        assert_eq!(retry.relations, baseline.relations);
        assert_eq!(
            file_hash(&dir.join("output.pile")),
            partial_hash,
            "retry touched partial attempt"
        );
        assert_eq!(file_hash(&source), before);
    }
    retain(temp);
}

#[test]
#[ignore = "manual actual deployed /32 writer fixtures; see module instructions"]
fn missing_foreign_refresh_and_local_substitution_cannot_complete() {
    let source = fixture("complete.pile");
    let before = file_hash(&source);
    let temp = workspace("foreign-");
    let refreshes = remote_refreshes();
    for (name, supplied) in [
        ("none", vec![]),
        ("missing-c", refreshes[..2].to_vec()),
        (
            "local-substitution",
            vec![CollectionRecord::Commit(CollectionCommit::sign(
                &key(7),
                Inline::new(payload(0)),
                Inline::new(payload(1)),
                Inline::new(payload(2)),
            ))],
        ),
    ] {
        let dir = temp.path().join(name);
        let result = attempt(&source, before, &dir, &key(7), &supplied, Stop::Never);
        assert!(!result.completed && !result.issues.is_empty());
        assert!(!dir.join("complete.test-only").exists());
        assert_eq!(
            result.ids.unwrap().assertions.len(),
            if name == "missing-c" { 7 } else { 5 }
        );
    }
    retain(temp);
}

#[test]
#[ignore = "manual actual deployed /32 writer fixtures; see module instructions"]
fn changed_foreign_fields_or_invalid_current_signature_are_not_refreshes() {
    let source = fixture("complete.pile");
    let frames = PileRecords::open(&source).unwrap();
    let bytes = frames.bytes().clone();
    let mut checked = 0;
    for frame in frames {
        let frame = frame.unwrap();
        let PileRecordContent::Opaque {
            kind: OpaqueKind::Described(kind),
        } = frame.content
        else {
            continue;
        };
        if !matches!(kind, old_frame::COMMIT | old_frame::DERIVE) {
            continue;
        }
        let old = old_frame::tagged(kind, &bytes[frame.offset..frame.offset + frame.len]).unwrap();
        if old[97..129] != key(8).verifying_key().to_bytes() {
            continue;
        }
        let bad = if old[0] == 1 {
            CollectionRecord::Commit(CollectionCommit::sign(
                &key(8),
                Inline::new(payload(0)),
                Inline::new(payload(1)),
                Inline::new(payload(5)),
            ))
        } else {
            CollectionRecord::Derive(CollectionDerive::sign(
                &key(8),
                Inline::new(payload(3)),
                SourceLocator::of(payload(5)),
                Inline::new(payload(4)),
            ))
        };
        assert!(matches!(
            legacy32::reseal_or_refresh(Input::TaggedCollection(&old), &key(7), Some(&bad)).outcome,
            Outcome::Unresolved(legacy32::Unresolved::RefreshMismatch)
        ));
        let mut corrupt = bad.to_bytes();
        *corrupt.last_mut().unwrap() ^= 1;
        assert!(CollectionRecord::from_bytes(&corrupt).is_err());
        checked += 1;
    }
    assert_eq!(checked, 2);
}

#[test]
#[ignore = "manual actual deployed /32 writer fixtures; see module instructions"]
fn non_eight_and_foreign_caches_remain_required_unresolved_evidence() {
    let temp = workspace("caches-");
    for name in ["non-eight.pile", "foreign-cache.pile"] {
        let source = fixture(name);
        let before = file_hash(&source);
        let dir = temp.path().join(name);
        let result = attempt(
            &source,
            before,
            &dir,
            &key(7),
            &remote_refreshes(),
            Stop::Never,
        );
        assert!(!result.completed);
        assert_eq!(result.issues.len(), 1, "{:?}", result.issues);
        assert_eq!(result.ids.unwrap().assertions.len(), 9);
        assert!(!dir.join("complete.test-only").exists());
        assert_eq!(file_hash(&source), before);
    }
    retain(temp);
}

#[test]
#[ignore = "manual actual deployed /32 writer fixtures; see module instructions"]
fn malformed_required_evidence_never_gets_a_completion_marker() {
    let source = fixture("complete.pile");
    let original = std::fs::read(&source).unwrap();
    // Ephemeral mutation locations; never mutate the producer's immutable file.
    let mut changes = Vec::new();
    for frame in PileRecords::open(&source).unwrap() {
        let frame = frame.unwrap();
        match frame.content {
            PileRecordContent::Blob {
                data_offset,
                data_len,
                ..
            } if data_len > 0 && changes.is_empty() => changes.push(("bad-blob", data_offset)),
            PileRecordContent::CapabilityProof {
                data_offset,
                data_len,
                ..
            } => changes.push(("bad-auth", data_offset + data_len - 1)),
            PileRecordContent::Opaque {
                kind: OpaqueKind::Described(old_frame::COMMIT),
            } if !changes.iter().any(|(name, _)| *name == "bad-signature") => {
                changes.push(("bad-signature", frame.offset + 255));
                changes.push(("unknown-kind", frame.offset + 32));
            }
            _ => {}
        }
    }
    assert_eq!(changes.len(), 4);
    let temp = workspace("malformed-");
    for (name, offset) in changes {
        let mut bytes = original.clone();
        bytes[offset] ^= 1; // Deliberate adversarial corruption, not a new stable kind.
        let input = temp.path().join(format!("{name}.pile"));
        fresh(&input).write_all(&bytes).unwrap();
        let before = file_hash(&input);
        let dir = temp.path().join(name);
        let result = attempt(
            &input,
            before,
            &dir,
            &key(7),
            &remote_refreshes(),
            Stop::Never,
        );
        assert!(!result.completed && !result.issues.is_empty(), "{name}");
        assert!(!dir.join("complete.test-only").exists());
        assert_eq!(file_hash(&input), before);
    }
    let input = temp.path().join("truncated.pile");
    fresh(&input)
        .write_all(&original[..original.len() - 1])
        .unwrap();
    let before = file_hash(&input);
    let dir = temp.path().join("truncated");
    let result = attempt(
        &input,
        before,
        &dir,
        &key(7),
        &remote_refreshes(),
        Stop::Never,
    );
    assert!(!result.completed && !result.issues.is_empty());
    assert!(!dir.join("complete.test-only").exists());
    assert_eq!(file_hash(&input), before);
    retain(temp);
}

#[test]
#[ignore = "manual actual deployed /32 writer fixtures; see module instructions"]
fn native_adapter_refuses_noncanonical_padding_count_and_span() {
    let frames = PileRecords::open(&fixture("non-eight.pile")).unwrap();
    let bytes = frames.bytes().clone();
    let mut tested = false;
    for frame in frames {
        let frame = frame.unwrap();
        let PileRecordContent::Opaque {
            kind: OpaqueKind::Described(old_frame::MERGE),
        } = frame.content
        else {
            continue;
        };
        let raw = &bytes[frame.offset..frame.offset + frame.len];
        if raw[255] != 2 {
            continue;
        }
        let mut corrupt = raw.to_vec();
        *corrupt.last_mut().unwrap() = 1;
        assert_eq!(
            old_frame::tagged(old_frame::MERGE, &corrupt),
            Err(old_frame::Error::Padding)
        );
        corrupt.copy_from_slice(raw);
        corrupt[255] = 17;
        assert_eq!(
            old_frame::tagged(old_frame::MERGE, &corrupt),
            Err(old_frame::Error::Count)
        );
        assert_eq!(
            old_frame::tagged(old_frame::MERGE, &raw[..256]),
            Err(old_frame::Error::Length)
        );
        assert_eq!(
            old_frame::tagged(old_frame::COMMIT, raw),
            Err(old_frame::Error::KindMismatch)
        );
        tested = true;
    }
    assert!(tested);
}
